import { PATH_SEPARATOR, ROOT_CONTEXT, ROOT_PATHWAY, parentContext } from './fit.js';
import { scorePositions, treePathways } from './analyze.js';
import type {
  BootstrapPathwaysResult,
  ContextTree,
  TreeComparison,
  TuneTreeResult,
} from './types.js';

export type TreePlotStyle = 'horizontal' | 'dendrogram' | 'icicle';

export interface SVGPlotOptions {
  width?: number;
  height?: number;
  title?: string;
  theme?: 'dark' | 'light';
}

export interface TreePlotOptions extends SVGPlotOptions {
  style?: TreePlotStyle;
  showLabels?: boolean;
  /** Draw at most this many contexts, the highest-count ones. A context tree has a longer
   *  history occurring no more often than its prefix, so the top-N by count is automatically
   *  ancestor-closed — a connected subtree, never floating branches. Omit to draw all. */
  maxNodes?: number;
}

export interface PathwayPlotOptions extends SVGPlotOptions {
  top?: number;
  sortBy?: 'count' | 'divergence' | 'depth';
  minCount?: number;
}

const COLORS = ['#63d7c0', '#8da7ff', '#ffbd69', '#ef7fa5', '#9add67', '#b98cff', '#5fc4ee', '#ff826d'];
const BG = 'var(--tt-bg)';
const GRID = 'var(--tt-grid)';
const TEXT = 'var(--tt-text)';
const MUTED = 'var(--tt-muted)';
const ORANGE = '#ff9f43';

function escape(value: unknown): string {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]!);
}

function number(value: number, digits = 3): string {
  if (Number.isNaN(value)) return 'NA';
  if (!Number.isFinite(value)) return '∞';
  return value.toFixed(digits).replace(/\.?0+$/, '');
}

function svg(width: number, height: number, content: string, label: string, theme: SVGPlotOptions['theme'] = 'light'): string {
  const variables = theme === 'light'
    ? '--tt-bg:#ffffff;--tt-text:#142638;--tt-muted:#536b80;--tt-grid:#d8e1e8'
    : '--tt-bg:#081421;--tt-text:#dce9f6;--tt-muted:#91a8bf;--tt-grid:#274159';
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="100%" style="${variables}" role="img" aria-label="${escape(label)}"><style>
    .tt-text{font-family:Inter,ui-sans-serif,system-ui,sans-serif;fill:${TEXT}} .tt-muted{fill:${MUTED}}
    .tt-axis{stroke:${GRID};stroke-width:1}.tt-label{font-size:12px}.tt-small{font-size:10px}
  </style><rect width="${width}" height="${height}" rx="16" fill="${BG}"/>${content}</svg>`;
}

function title(text: string, width: number): string {
  return `<text class="tt-text" x="24" y="30" font-size="16" font-weight="700">${escape(text)}</text><line class="tt-axis" x1="24" y1="42" x2="${width - 24}" y2="42"/>`;
}

function color(index: number): string {
  return COLORS[index % COLORS.length]!;
}

function mixHex(from: string, to: string, amount: number): string {
  const value = Math.max(0, Math.min(1, amount));
  const channel = (hex: string, offset: number): number => Number.parseInt(hex.slice(offset, offset + 2), 16);
  const mixed = [1, 3, 5].map((offset) => Math.round(channel(from, offset) + (channel(to, offset) - channel(from, offset)) * value));
  return `#${mixed.map((entry) => entry.toString(16).padStart(2, '0')).join('')}`;
}

function stateOf(context: string): string {
  if (context === ROOT_CONTEXT) return ROOT_PATHWAY;
  const parts = context.split(PATH_SEPARATOR);
  return parts[parts.length - 1]!;
}

function stateColor(tree: ContextTree, context: string): string {
  if (context === ROOT_CONTEXT) return '#d9e5f2';
  return color(Math.max(tree.alphabet.indexOf(stateOf(context)), 0));
}

interface TreePoint {
  context: string;
  x: number;
  y: number;
}

function treeLayout(tree: ContextTree, width: number, height: number, keep?: Set<string>): TreePoint[] {
  const shown = (context: string): boolean => !keep || keep.has(context);
  const children = new Map<string, string[]>();
  for (const edge of tree.edges) {
    if (!shown(edge.parent) || !shown(edge.child)) continue;
    children.set(edge.parent, [...(children.get(edge.parent) ?? []), edge.child]);
  }
  for (const list of children.values()) list.sort((left, right) => tree.nodes[right]!.count - tree.nodes[left]!.count);
  let leaf = 0;
  const positions = new Map<string, number>();
  const visit = (context: string): number => {
    const descendants = children.get(context) ?? [];
    if (descendants.length === 0) {
      const value = leaf++;
      positions.set(context, value);
      return value;
    }
    const values = descendants.map(visit);
    const value = values.reduce((sum, item) => sum + item, 0) / values.length;
    positions.set(context, value);
    return value;
  };
  visit(tree.localRoot ?? ROOT_CONTEXT);   // the root is always kept (highest count)
  const maxLeaf = Math.max(leaf - 1, 1);
  const maxDepth = Math.max(...[...positions.keys()].map((context) => tree.nodes[context]!.depth), 1);
  return [...positions].map(([context, row]) => ({
    context,
    x: 54 + tree.nodes[context]!.depth / maxDepth * (width - 300),
    y: 68 + row / maxLeaf * (height - 104),
  }));
}

function horizontalTree(tree: ContextTree, options: TreePlotOptions): string {
  const width = options.width ?? 980;
  const allContexts = Object.keys(tree.nodes);
  // Cap to the highest-count contexts when asked (see maxNodes). Ancestor-closed by the
  // count-monotonicity of a context tree, so the kept set is a connected subtree.
  const cap = options.maxNodes ?? Infinity;
  const keep = allContexts.length > cap
    ? new Set(allContexts.slice().sort((a, b) => tree.nodes[b]!.count - tree.nodes[a]!.count).slice(0, cap))
    : undefined;
  const count = keep ? keep.size : allContexts.length;
  // 16px per node (was 30): a real suffix tree has hundreds of contexts, and at 30px the
  // phylogram ran to ~8000px. The 11px node labels are the binding constraint, so 16px keeps
  // them legible while roughly halving the height.
  const height = options.height ?? Math.max(430, count * 16);
  const points = treeLayout(tree, width, height, keep);
  const lookup = new Map(points.map((point) => [point.context, point]));
  const maximum = Math.max(...Object.values(tree.nodes).map((node) => node.count));
  const edges = tree.edges.map((edge) => {
    const from = lookup.get(edge.parent);
    const to = lookup.get(edge.child);
    if (!from || !to) return '';
    const thickness = 0.7 + 5 * Math.sqrt(tree.nodes[edge.child]!.count / maximum);
    const middle = (from.x + to.x) / 2;
    return `<path d="M${from.x},${from.y} C${middle},${from.y} ${middle},${to.y} ${to.x},${to.y}" fill="none" stroke="#50728d" stroke-width="${thickness}" opacity=".72"><title>${escape(edge.child)} · n=${number(tree.nodes[edge.child]!.count, 1)}</title></path>`;
  }).join('');
  const nodes = points.map((point) => {
    const node = tree.nodes[point.context]!;
    const radius = 4 + 7 * Math.sqrt(node.count / maximum);
    const modal = tree.alphabet[node.probability.indexOf(Math.max(...node.probability))]!;
    const label = point.context === ROOT_CONTEXT ? ROOT_PATHWAY : point.context;
    return `<g><circle cx="${point.x}" cy="${point.y}" r="${radius}" fill="${stateColor(tree, point.context)}" stroke="#e8f2fb" stroke-width="1.2"><title>${escape(label)} · n=${number(node.count, 1)} · next ${escape(modal)} (${number(Math.max(...node.probability))})</title></circle>${options.showLabels === false ? '' : `<text class="tt-text tt-small" x="${point.x + radius + 7}" y="${point.y + 4}">${escape(label)} → ${escape(modal)}</text>`}</g>`;
  }).join('');
  return svg(width, height, title(options.title ?? 'Horizontal prediction suffix tree', width) + edges + nodes, 'Horizontal prediction suffix tree', options.theme);
}

function radialTree(tree: ContextTree, options: TreePlotOptions): string {
  const width = options.width ?? 760;
  const height = options.height ?? 700;
  const base = treeLayout(tree, 800, 700);
  const maxDepth = Math.max(...base.map((point) => tree.nodes[point.context]!.depth), 1);
  const minY = Math.min(...base.map((point) => point.y));
  const maxY = Math.max(...base.map((point) => point.y));
  const centerX = width / 2;
  const centerY = height / 2 + 12;
  const maximumRadius = Math.min(width, height) * .4;
  const points = base.map((point) => {
    const angle = (point.y - minY) / Math.max(maxY - minY, 1) * Math.PI * 2 - Math.PI / 2;
    const radius = (tree.nodes[point.context]!.depth / maxDepth) * maximumRadius;
    return { context: point.context, x: centerX + Math.cos(angle) * radius, y: centerY + Math.sin(angle) * radius };
  });
  const lookup = new Map(points.map((point) => [point.context, point]));
  const maximum = Math.max(...Object.values(tree.nodes).map((node) => node.count));
  const edges = tree.edges.map((edge) => {
    const from = lookup.get(edge.parent); const to = lookup.get(edge.child);
    if (!from || !to) return '';
    return `<line x1="${from.x}" y1="${from.y}" x2="${to.x}" y2="${to.y}" stroke="#567792" opacity=".7" stroke-width="${.7 + 5 * Math.sqrt(tree.nodes[edge.child]!.count / maximum)}"/>`;
  }).join('');
  const nodes = points.map((point) => {
    const node = tree.nodes[point.context]!;
    const modal = tree.alphabet[node.probability.indexOf(Math.max(...node.probability))]!;
    return `<circle cx="${point.x}" cy="${point.y}" r="${4 + 8 * Math.sqrt(node.count / maximum)}" fill="${stateColor(tree, point.context)}" stroke="#eff7ff"><title>${escape(point.context === ROOT_CONTEXT ? ROOT_PATHWAY : point.context)} · n=${number(node.count, 1)} · next ${escape(modal)}</title></circle>`;
  }).join('');
  return svg(width, height, title(options.title ?? 'Radial dendrogram', width) + edges + nodes, 'Radial context-tree dendrogram', options.theme);
}

interface Partition {
  context: string;
  start: number;
  end: number;
}

function icicleTree(tree: ContextTree, options: TreePlotOptions): string {
  const width = options.width ?? 900;
  const height = options.height ?? 580;
  const children = new Map<string, string[]>();
  for (const edge of tree.edges) children.set(edge.parent, [...(children.get(edge.parent) ?? []), edge.child]);
  const partitions: Partition[] = [];
  const visit = (context: string, start: number, end: number): void => {
    partitions.push({ context, start, end });
    const descendants = children.get(context) ?? [];
    const total = descendants.reduce((value, child) => value + tree.nodes[child]!.count, 0);
    let cursor = start;
    for (const child of descendants) {
      const next = total === 0 ? cursor : cursor + (end - start) * tree.nodes[child]!.count / total;
      visit(child, cursor, next);
      cursor = next;
    }
  };
  visit(tree.localRoot ?? ROOT_CONTEXT, 0, 1);
  const maxDepth = Math.max(...partitions.map((item) => tree.nodes[item.context]!.depth), 1);
  const left = 26; const top = 58; const plotWidth = width - 52; const plotHeight = height - 86;
  const cells = partitions.map((item) => {
    const depth = tree.nodes[item.context]!.depth;
    const x = left + depth / (maxDepth + 1) * plotWidth;
    const cellWidth = plotWidth / (maxDepth + 1) - 3;
    const y = top + item.start * plotHeight;
    const cellHeight = Math.max((item.end - item.start) * plotHeight - 2, 1);
    const label = item.context === ROOT_CONTEXT ? ROOT_PATHWAY : item.context;
    return `<g><rect x="${x}" y="${y}" width="${cellWidth}" height="${cellHeight}" rx="3" fill="${stateColor(tree, item.context)}" opacity="${.45 + .5 * (depth + 1) / (maxDepth + 1)}"><title>${escape(label)} · n=${number(tree.nodes[item.context]!.count, 1)}</title></rect>${cellHeight > 15 && options.showLabels !== false ? `<text class="tt-text tt-small" x="${x + 6}" y="${y + Math.min(cellHeight / 2 + 4, 16)}">${escape(stateOf(item.context))}</text>` : ''}</g>`;
  }).join('');
  return svg(width, height, title(options.title ?? 'Count-proportional icicle', width) + cells, 'Count-proportional context-tree icicle', options.theme);
}

export function plotTree(tree: ContextTree, options: TreePlotOptions = {}): string {
  if ((options.style ?? 'horizontal') === 'dendrogram') return radialTree(tree, options);
  if (options.style === 'icicle') return icicleTree(tree, options);
  return horizontalTree(tree, options);
}

export function plotPathways(tree: ContextTree, options: PathwayPlotOptions = {}): string {
  const rows = treePathways(tree, { sortBy: options.sortBy ?? 'count', minCount: options.minCount }).slice(0, options.top ?? 12);
  const width = options.width ?? 900;
  const rowHeight = 28;
  const height = options.height ?? 78 + rows.length * rowHeight;
  const labelWidth = 260;
  const cellWidth = (width - labelWidth - 28) / tree.alphabet.length;
  const cells = rows.map((row, rowIndex) => {
    const context = row.pathway === ROOT_PATHWAY ? ROOT_CONTEXT : row.pathway;
    const node = tree.nodes[context]!;
    const modal = node.probability.indexOf(Math.max(...node.probability));
    const prefix = row.changesPrediction ? '› ' : '';
    const label = `<text class="tt-text tt-small" x="20" y="${70 + rowIndex * rowHeight}">${escape(prefix + row.pathway)}</text>`;
    return label + tree.alphabet.map((state, stateIndex) => {
      const probability = node.probability[stateIndex]!;
      const x = labelWidth + stateIndex * cellWidth;
      const y = 52 + rowIndex * rowHeight;
      return `<g><rect x="${x}" y="${y}" width="${cellWidth - 3}" height="${rowHeight - 3}" rx="3" fill="${color(stateIndex)}" opacity="${.08 + .92 * probability}"><title>${escape(row.pathway)} · P(${escape(state)})=${number(probability)}</title></rect><text class="tt-text tt-small" x="${x + cellWidth / 2}" y="${y + 17}" text-anchor="middle" font-weight="${stateIndex === modal ? 800 : 400}">${number(probability, 2)}</text></g>`;
    }).join('');
  }).join('');
  const headers = tree.alphabet.map((state, index) => `<text class="tt-muted tt-small" x="${labelWidth + index * cellWidth + cellWidth / 2}" y="42" text-anchor="middle">${escape(state)}</text>`).join('');
  return svg(width, height, title(options.title ?? 'Next-state probability by context', width) + headers + cells, 'Next-state probability heatmap', options.theme);
}

export function plotDivergence(tree: ContextTree, options: PathwayPlotOptions = {}): string {
  const rows = treePathways(tree, { sortBy: 'divergence', minCount: options.minCount }).filter((row) => Number.isFinite(row.divergence)).slice(0, options.top ?? 12);
  const width = options.width ?? 900; const height = options.height ?? 76 + rows.length * 30;
  const left = 250; const right = 35; const maximum = Math.max(...rows.map((row) => row.divergence), 1e-9);
  const marks = rows.map((row, index) => {
    const y = 62 + index * 30; const x = left + row.divergence / maximum * (width - left - right);
    return `<text class="tt-text tt-small" x="18" y="${y + 4}">${escape(row.pathway)}</text><line x1="${left}" y1="${y}" x2="${x}" y2="${y}" stroke="#617f98" stroke-width="2"/><circle cx="${x}" cy="${y}" r="6" fill="${row.changesPrediction ? ORANGE : '#67d6c0'}"><title>KL=${number(row.divergence)} · n=${number(row.count, 1)}</title></circle>`;
  }).join('');
  return svg(width, height, title(options.title ?? 'Divergence from shorter-history prediction', width) + `<line class="tt-axis" x1="${left}" y1="50" x2="${left}" y2="${height - 18}"/>` + marks, 'Context divergence lollipop chart', options.theme);
}

export function plotDistributions(tree: ContextTree, options: PathwayPlotOptions = {}): string {
  const rows = treePathways(tree, { sortBy: options.sortBy ?? 'count', minCount: options.minCount }).slice(0, options.top ?? 8);
  const width = options.width ?? 900; const height = options.height ?? 70 + rows.length * 44; const left = 250; const plotWidth = width - left - 35;
  const marks = rows.map((row, index) => {
    const context = row.pathway === ROOT_PATHWAY ? ROOT_CONTEXT : row.pathway;
    const probability = tree.nodes[context]!.probability;
    let cursor = left;
    const bars = tree.alphabet.map((state, stateIndex) => {
      const segmentWidth = probability[stateIndex]! * plotWidth;
      const result = `<rect x="${cursor}" y="${54 + index * 44}" width="${Math.max(segmentWidth, .5)}" height="26" fill="${color(stateIndex)}"><title>${escape(state)} ${number(probability[stateIndex]!)}</title></rect>`;
      cursor += segmentWidth;
      return result;
    }).join('');
    return `<text class="tt-text tt-small" x="18" y="${71 + index * 44}">${escape(row.pathway)}</text>${bars}`;
  }).join('');
  const legend = tree.alphabet.map((state, index) => `<rect x="${left + index * 125}" y="${height - 18}" width="10" height="10" fill="${color(index)}"/><text class="tt-muted tt-small" x="${left + 15 + index * 125}" y="${height - 9}">${escape(state)}</text>`).join('');
  return svg(width, height + 12, title(options.title ?? 'Per-context next-state distributions', width) + marks + legend, 'Per-context probability distributions', options.theme);
}

export function plotPruning(
  tree: ContextTree,
  pathway: string,
  pruned: ContextTree,
  options: SVGPlotOptions = {},
): string {
  const normalized = pathway === ROOT_PATHWAY ? ROOT_CONTEXT : pathway;
  if (!tree.nodes[normalized]) throw new Error(`pathway '${pathway}' is not in the source tree`);
  const chain: string[] = [];
  let current: string | null = normalized;
  while (current !== null) { chain.push(current); current = parentContext(current); }
  const width = options.width ?? 920; const height = options.height ?? 100 + chain.length * 58;
  const marks = chain.map((context, index) => {
    const node = tree.nodes[context]!; const kept = pruned.nodes[context] !== undefined;
    const modal = node.probability.indexOf(Math.max(...node.probability));
    const y = 70 + index * 58;
    const bars = tree.alphabet.map((state, stateIndex) => `<rect x="${390 + stateIndex * 145}" y="${y - 14}" width="${node.probability[stateIndex]! * 115}" height="18" rx="3" fill="${color(stateIndex)}" opacity="${kept ? .95 : .28}"><title>${escape(state)} ${number(node.probability[stateIndex]!)}</title></rect>`).join('');
    return `${index < chain.length - 1 ? `<line x1="46" y1="${y + 9}" x2="46" y2="${y + 44}" stroke="${GRID}" stroke-width="2"/>` : ''}<circle cx="46" cy="${y}" r="9" fill="${kept ? '#63d7c0' : '#5f6d79'}"/><text class="tt-text tt-label" x="68" y="${y + 4}" opacity="${kept ? 1 : .45}">${escape(context === ROOT_CONTEXT ? ROOT_PATHWAY : context)}</text><text class="tt-muted tt-small" x="300" y="${y + 4}">n=${number(node.count, 1)} · ${escape(tree.alphabet[modal]!)}</text>${bars}`;
  }).join('');
  return svg(width, height, title(options.title ?? 'Suffix memory retained by pruning', width) + marks, 'Pruning suffix-chain diagnostic', options.theme);
}

export function plotPredictive(
  tree: ContextTree,
  data: readonly (readonly (string | null)[])[],
  options: SVGPlotOptions & { type?: 'logloss' | 'ecdf' | 'position' } = {},
): string {
  const type = options.type ?? 'logloss'; const rows = scorePositions(tree, data);
  const width = options.width ?? 900; const height = options.height ?? 430;
  const left = 58; const top = 58; const plotWidth = width - 88; const plotHeight = height - 105;
  if (type === 'ecdf') {
    const values = rows.map((row) => row.predictedProbability).sort((a, b) => a - b);
    const path = values.map((value, index) => `${index ? 'L' : 'M'}${left + value * plotWidth},${top + plotHeight - (index + 1) / values.length * plotHeight}`).join(' ');
    return svg(width, height, title(options.title ?? 'ECDF of assigned probability', width) + axes(left, top, plotWidth, plotHeight, 'assigned probability', 'cumulative share') + `<path d="${path}" fill="none" stroke="#63d7c0" stroke-width="3"/>`, 'Predictive probability empirical CDF', options.theme);
  }
  const maxPosition = Math.max(...rows.map((row) => row.position), 1);
  const grouped = new Map<number, typeof rows>();
  for (const row of rows) grouped.set(row.sequenceId, [...(grouped.get(row.sequenceId) ?? []), row]);
  if (type === 'position') {
    const paths = [...grouped].map(([sequenceId, values], index) => {
      const points = values.map((row) => `${left + (row.position - 1) / Math.max(maxPosition - 1, 1) * plotWidth},${top + (1 - row.predictedProbability) * plotHeight}`).join(' ');
      return `<polyline points="${points}" fill="none" stroke="${color(index)}" stroke-width="1.8" opacity=".7"><title>Sequence ${sequenceId}</title></polyline>`;
    }).join('');
    return svg(width, height, title(options.title ?? 'Prediction confidence by position', width) + axes(left, top, plotWidth, plotHeight, 'position', 'assigned probability') + paths, 'Per-sequence prediction confidence', options.theme);
  }
  const maxLoss = Math.max(...rows.map((row) => -row.logLikelihood / Math.log(2)).filter(Number.isFinite), Math.log2(tree.alphabet.length));
  const points = rows.map((row) => {
    const loss = -row.logLikelihood / Math.log(2);
    const x = left + (row.position - 1) / Math.max(maxPosition - 1, 1) * plotWidth;
    const y = top + loss / maxLoss * plotHeight;
    return `<circle cx="${x}" cy="${y}" r="3" fill="#8da7ff" opacity=".42"><title>sequence ${row.sequenceId}, position ${row.position}: ${number(loss)} bits</title></circle>`;
  }).join('');
  const uniformY = top + Math.log2(tree.alphabet.length) / maxLoss * plotHeight;
  return svg(width, height, title(options.title ?? 'Per-position predictive surprise', width) + axes(left, top, plotWidth, plotHeight, 'position', 'log loss (bits)') + `<line x1="${left}" y1="${uniformY}" x2="${left + plotWidth}" y2="${uniformY}" stroke="${ORANGE}" stroke-dasharray="7 5"><title>uniform prediction</title></line>` + points, 'Position-level predictive log loss', options.theme);
}

function axes(left: number, top: number, width: number, height: number, xLabel: string, yLabel: string): string {
  return `<line class="tt-axis" x1="${left}" y1="${top + height}" x2="${left + width}" y2="${top + height}"/><line class="tt-axis" x1="${left}" y1="${top}" x2="${left}" y2="${top + height}"/><text class="tt-muted tt-small" x="${left + width / 2}" y="${top + height + 30}" text-anchor="middle">${escape(xLabel)}</text><text class="tt-muted tt-small" x="16" y="${top + height / 2}" transform="rotate(-90 16 ${top + height / 2})" text-anchor="middle">${escape(yLabel)}</text>`;
}

interface TrieNode {
  key: string;
  depth: number;
  count: number;
  probability: number;
  parent: string | null;
  state: string;
}

export function plotTrajectories(
  tree: ContextTree,
  options: SVGPlotOptions & { measure?: 'frequency' | 'predictability'; minCount?: number; maxDepth?: number } = {},
): string {
  const maxDepth = options.maxDepth ?? Math.max(...tree.data.map((sequence) => sequence.length));
  const minCount = options.minCount ?? 4;
  const measure = options.measure ?? 'frequency';
  const allNodes = new Map<string, TrieNode>();
  allNodes.set(ROOT_CONTEXT, { key: ROOT_CONTEXT, depth: 0, count: tree.data.length, probability: 1, parent: null, state: ROOT_PATHWAY });
  for (const source of tree.data) {
    const sequence = source.filter((state): state is string => state !== null && state !== '').slice(0, maxDepth);
    for (let depth = 1; depth <= sequence.length; depth++) {
      const prefix = sequence.slice(0, depth); const key = prefix.join(PATH_SEPARATOR); const parent = depth === 1 ? ROOT_CONTEXT : prefix.slice(0, -1).join(PATH_SEPARATOR);
      const existing = allNodes.get(key);
      if (existing) existing.count++;
      else {
        const history = prefix.slice(0, -1); const matched = (() => {
          for (let d = Math.min(tree.maxDepth, history.length); d >= 1; d--) { const candidate = history.slice(-d).join(PATH_SEPARATOR); if (tree.nodes[candidate]) return candidate; }
          return ROOT_CONTEXT;
        })();
        const stateIndex = tree.alphabet.indexOf(prefix[prefix.length - 1]!);
        allNodes.set(key, { key, depth, count: 1, probability: tree.nodes[matched]!.probability[stateIndex] ?? 0, parent, state: prefix[prefix.length - 1]! });
      }
    }
  }
  const retained = new Map<string, TrieNode>();
  retained.set(ROOT_CONTEXT, allNodes.get(ROOT_CONTEXT)!);
  const ordered = [...allNodes.values()].filter((node) => node.depth > 0).sort((left, right) => left.depth - right.depth || right.count - left.count);
  for (const node of ordered) {
    if (node.count >= minCount && node.parent !== null && retained.has(node.parent)) retained.set(node.key, node);
  }
  if (retained.size === 1) throw new Error(`no forward prefix occurs at least ${minCount} times`);

  const children = new Map<string, string[]>();
  for (const node of retained.values()) {
    if (!node.parent) continue;
    children.set(node.parent, [...(children.get(node.parent) ?? []), node.key]);
  }
  for (const entries of children.values()) entries.sort((left, right) => {
    const stateOrder = tree.alphabet.indexOf(retained.get(left)!.state) - tree.alphabet.indexOf(retained.get(right)!.state);
    return stateOrder || retained.get(right)!.count - retained.get(left)!.count;
  });

  let leaf = 0;
  const row = new Map<string, number>();
  const place = (key: string): number => {
    const descendants = children.get(key) ?? [];
    if (descendants.length === 0) {
      const value = leaf++;
      row.set(key, value);
      return value;
    }
    const values = descendants.map(place);
    const value = values.reduce((total, entry) => total + entry, 0) / values.length;
    row.set(key, value);
    return value;
  };
  place(ROOT_CONTEXT);

  const deepest = Math.max(...[...retained.values()].map((node) => node.depth));
  const width = options.width ?? Math.max(980, 190 + deepest * 150);
  const height = options.height ?? Math.max(430, 145 + Math.max(leaf - 1, 1) * 50);
  const left = 74; const right = 60; const top = 105; const bottom = 70;
  const plotWidth = width - left - right; const plotHeight = height - top - bottom;
  const x = (depth: number): number => left + depth / Math.max(deepest, 1) * plotWidth;
  const y = (key: string): number => top + (row.get(key) ?? 0) / Math.max(leaf - 1, 1) * plotHeight;
  const nonRoot = [...retained.values()].filter((node) => node.depth > 0);
  const counts = nonRoot.map((node) => node.count);
  const minFlow = Math.min(...counts); const maxFlow = Math.max(...counts);
  const scale = (node: TrieNode): number => measure === 'predictability'
    ? node.probability
    : (node.count - minFlow) / Math.max(maxFlow - minFlow, 1);
  const fill = (node: TrieNode): string => mixHex('#d9eef0', '#155d58', scale(node));
  const textFill = (node: TrieNode): string => scale(node) > .48 ? '#ffffff' : '#132f3a';
  const flowWidth = (node: TrieNode): number => 1 + 7 * (node.count - minFlow) / Math.max(maxFlow - minFlow, 1);

  const depthGuides = Array.from({ length: deepest + 1 }, (_, depth) => `<line x1="${x(depth)}" y1="${top - 35}" x2="${x(depth)}" y2="${height - bottom + 18}" stroke="${GRID}" stroke-dasharray="3 6"/><text class="tt-muted tt-small" x="${x(depth)}" y="${height - 24}" text-anchor="middle">${depth === 0 ? 'start' : `move ${depth}`}</text>`).join('');
  const edges = nonRoot.map((node) => {
    const parent = retained.get(node.parent!)!;
    const fromX = x(parent.depth) + (parent.depth === 0 ? 25 : 34);
    const toX = x(node.depth) - 34;
    const fromY = y(parent.key);
    const toY = y(node.key);
    const middle = (fromX + toX) / 2;
    return `<path d="M${fromX},${fromY} C${middle},${fromY} ${middle},${toY} ${toX},${toY}" fill="none" stroke="${fill(node)}" stroke-width="${flowWidth(node)}" stroke-linecap="round" opacity=".9"><title>${escape(node.key)} · n=${node.count} · P(move | history)=${number(node.probability)}</title></path>`;
  }).join('');
  const boxes = nonRoot.map((node) => {
    const cx = x(node.depth); const cy = y(node.key); const metric = measure === 'frequency' ? `n=${node.count}` : `${number(node.probability * 100, 0)}%`;
    return `<g><rect x="${cx - 34}" y="${cy - 15}" width="68" height="30" rx="9" fill="${fill(node)}" stroke="#8da4b6" stroke-width=".8"><title>${escape(node.key)} · n=${node.count} · P=${number(node.probability)}</title></rect><text x="${cx}" y="${cy + 3}" text-anchor="middle" font-family="Inter,ui-sans-serif,system-ui,sans-serif" font-size="10" font-weight="800" fill="${textFill(node)}">${escape(node.state)}</text><text class="tt-muted tt-small" x="${cx}" y="${cy + 26}" text-anchor="middle">${metric}</text></g>`;
  }).join('');
  const rootX = x(0); const rootY = y(ROOT_CONTEXT);
  const root = `<g><rect x="${rootX - 25}" y="${rootY - 18}" width="50" height="36" rx="11" fill="#31475b" stroke="#c7d6e3"/><text class="tt-text tt-small" x="${rootX}" y="${rootY + 4}" text-anchor="middle" font-weight="800">start</text></g>`;
  const legendX = width - 238; const legendY = 59;
  const legend = `<defs><linearGradient id="tt-trajectory-gradient"><stop offset="0" stop-color="#d9eef0"/><stop offset="1" stop-color="#155d58"/></linearGradient></defs><text class="tt-muted tt-small" x="${legendX}" y="${legendY - 8}">${measure === 'frequency' ? 'sequence frequency' : 'P(move | history)'}</text><rect x="${legendX}" y="${legendY}" width="190" height="10" rx="5" fill="url(#tt-trajectory-gradient)"/><text class="tt-muted tt-small" x="${legendX}" y="${legendY + 25}">low</text><text class="tt-muted tt-small" x="${legendX + 190}" y="${legendY + 25}" text-anchor="end">high</text>`;
  const subtitle = measure === 'frequency'
    ? 'node colour and ribbon width encode sequences following each prefix'
    : 'node colour encodes conditional probability; ribbon width still encodes sequence flow';
  const heading = title(options.title ?? `Forward trajectory tree · ${measure}`, width) + `<text class="tt-muted tt-small" x="24" y="62">${subtitle}</text>`;
  return svg(width, height, heading + legend + depthGuides + edges + root + boxes, 'Forward prefix trajectory flow tree', options.theme);
}

export function plotBootstrap(result: BootstrapPathwaysResult, options: SVGPlotOptions & { top?: number } = {}): string {
  const rows = result.summary.filter((row) => Number.isFinite(row.g2)).slice(0, options.top ?? 14);
  const width = options.width ?? 920; const height = options.height ?? 82 + rows.length * 31; const left = 245; const right = 35;
  const maximum = Math.max(result.g2CriticalValue, ...rows.flatMap((row) => [row.g2CI[1], row.g2]));
  const x = (value: number): number => left + Math.max(0, value) / maximum * (width - left - right);
  const criticalX = x(result.g2CriticalValue);
  const marks = rows.map((row, index) => {
    const y = 65 + index * 31; const trust = row.stable && row.informative ? '#63d7c0' : row.informative ? ORANGE : row.stable ? '#8da7ff' : '#6e7d8b';
    return `<text class="tt-text tt-small" x="18" y="${y + 4}">${escape(row.pathway)}</text><line x1="${x(row.g2CI[0])}" y1="${y}" x2="${x(row.g2CI[1])}" y2="${y}" stroke="${trust}" stroke-width="4"/><circle cx="${x(row.g2)}" cy="${y}" r="5" fill="${trust}"><title>G² ${number(row.g2)} · CI [${number(row.g2CI[0])}, ${number(row.g2CI[1])}]</title></circle>`;
  }).join('');
  return svg(width, height, title(options.title ?? 'Bootstrap G² forest plot', width) + `<line x1="${criticalX}" y1="50" x2="${criticalX}" y2="${height - 18}" stroke="${ORANGE}" stroke-width="2" stroke-dasharray="6 5"><title>χ² critical value ${number(result.g2CriticalValue)}</title></line>` + marks, 'Bootstrap confidence-interval forest plot', options.theme);
}

export function plotPathwayResamples(
  result: BootstrapPathwaysResult,
  options: SVGPlotOptions & { statistic?: 'count' | 'nextProbability' | 'divergence' | 'g2'; top?: number } = {},
): string {
  if (!result.resamples) throw new Error('resamples were not retained');
  const statistic = options.statistic ?? 'divergence'; const top = options.top ?? 6;
  const rows = result.summary.slice(0, top); const width = options.width ?? 920; const panelHeight = 100; const height = options.height ?? 58 + rows.length * panelHeight;
  const matrix = result.resamples[statistic];
  const marks = rows.map((row, rowIndex) => {
    const pathwayIndex = result.pathways.findIndex((candidate) => candidate.pathway === row.pathway);
    const values = matrix.map((sample) => sample[pathwayIndex]!).filter(Number.isFinite);
    const min = Math.min(...values); const max = Math.max(...values); const bins = 18; const counts = new Array<number>(bins).fill(0);
    for (const value of values) { const index = max === min ? 0 : Math.min(Math.floor((value - min) / (max - min) * bins), bins - 1); counts[index] = counts[index]! + 1; }
    const maximum = Math.max(...counts, 1); const left = 250; const plotWidth = width - left - 30; const yBase = 132 + rowIndex * panelHeight;
    const bars = counts.map((count, index) => `<rect x="${left + index / bins * plotWidth}" y="${yBase - count / maximum * 62}" width="${plotWidth / bins - 2}" height="${count / maximum * 62}" fill="#8da7ff" opacity=".78"/>`).join('');
    return `<text class="tt-text tt-small" x="18" y="${yBase - 26}">${escape(row.pathway)}</text>${bars}<text class="tt-muted tt-small" x="${left}" y="${yBase + 15}">${number(min)}</text><text class="tt-muted tt-small" x="${left + plotWidth}" y="${yBase + 15}" text-anchor="end">${number(max)}</text>`;
  }).join('');
  return svg(width, height, title(options.title ?? `Bootstrap resamples · ${statistic}`, width) + marks, 'Bootstrap pathway resample distributions', options.theme);
}

export function plotComparison(result: TreeComparison, options: SVGPlotOptions = {}): string {
  const width = options.width ?? 900; const height = options.height ?? 430; const left = 58; const top = 62; const plotWidth = width - 92; const plotHeight = height - 112;
  const values = result.nullDistribution; const min = Math.min(...values, result.distance); const max = Math.max(...values, result.distance); const bins = 28; const counts = new Array<number>(bins).fill(0);
  for (const value of values) { const index = max === min ? 0 : Math.min(Math.floor((value - min) / (max - min) * bins), bins - 1); counts[index] = counts[index]! + 1; }
  const maximum = Math.max(...counts, 1);
  const bars = counts.map((count, index) => `<rect x="${left + index / bins * plotWidth}" y="${top + plotHeight - count / maximum * plotHeight}" width="${plotWidth / bins - 2}" height="${count / maximum * plotHeight}" fill="#7890a6" opacity=".78"/>`).join('');
  const observedX = left + (result.distance - min) / Math.max(max - min, 1e-12) * plotWidth;
  return svg(width, height, title(options.title ?? `Permutation null · p=${number(result.pValue)}`, width) + axes(left, top, plotWidth, plotHeight, 'tree distance', 'permutations') + bars + `<line x1="${observedX}" y1="${top}" x2="${observedX}" y2="${top + plotHeight}" stroke="${ORANGE}" stroke-width="4"><title>observed ${number(result.distance)}</title></line>`, 'Permutation null distribution', options.theme);
}

export function plotTuning(result: TuneTreeResult, options: SVGPlotOptions = {}): string {
  const rows = result.rows.filter((row) => Number.isFinite(row.perplexity)); const width = options.width ?? 920; const height = options.height ?? 460; const left = 62; const top = 62; const plotWidth = width - 100; const plotHeight = height - 118;
  const depths = rows.map((row) => row.maxDepth); const minDepth = Math.min(...depths); const maxDepth = Math.max(...depths); const perplexities = rows.map((row) => row.perplexity); const minP = Math.min(...perplexities); const maxP = Math.max(...perplexities);
  const key = (row: typeof rows[number]): string => `${row.smoothing} · n≥${row.minCount} · ${row.prune ? 'pruned' : 'full'}`;
  const groups = new Map<string, typeof rows>(); for (const row of rows) groups.set(key(row), [...(groups.get(key(row)) ?? []), row]);
  const x = (value: number): number => left + (value - minDepth) / Math.max(maxDepth - minDepth, 1) * plotWidth;
  const y = (value: number): number => top + (value - minP) / Math.max(maxP - minP, 1e-12) * plotHeight;
  const lines = [...groups].map(([name, values], index) => {
    values.sort((a, b) => a.maxDepth - b.maxDepth);
    return `<polyline points="${values.map((row) => `${x(row.maxDepth)},${y(row.perplexity)}`).join(' ')}" fill="none" stroke="${color(index)}" stroke-width="2" opacity=".72"><title>${escape(name)}</title></polyline>${values.map((row) => `<circle cx="${x(row.maxDepth)}" cy="${y(row.perplexity)}" r="4" fill="${color(index)}"><title>${escape(name)} · perplexity ${number(row.perplexity)}</title></circle>`).join('')}`;
  }).join('');
  const best = result.best ? `<text x="${x(result.best.maxDepth)}" y="${y(result.best.perplexity) - 10}" text-anchor="middle" fill="${ORANGE}" font-size="24">★</text>` : '';
  return svg(width, height, title(options.title ?? 'Cross-validated tuning surface', width) + axes(left, top, plotWidth, plotHeight, 'maximum depth', 'perplexity') + lines + best, 'Cross-validated perplexity tuning surface', options.theme);
}

export function plotGroupDifference(
  trees: Record<string, ContextTree>,
  options: SVGPlotOptions & { depth?: number; groups?: [string, string] } = {},
): string {
  const names = options.groups ?? Object.keys(trees).slice(0, 2) as [string, string];
  if (names.length !== 2 || !trees[names[0]] || !trees[names[1]]) throw new Error('two valid groups are required');
  const leftTree = trees[names[0]]!; const rightTree = trees[names[1]]!; const alphabet = leftTree.alphabet; const depth = options.depth ?? 1;
  const contexts = [...new Set([...Object.keys(leftTree.nodes), ...Object.keys(rightTree.nodes)])].filter((context) => leftTree.nodes[context]?.depth === depth || rightTree.nodes[context]?.depth === depth);
  const width = options.width ?? 900; const rowHeight = 34; const height = options.height ?? 78 + contexts.length * rowHeight; const labelWidth = 250; const cellWidth = (width - labelWidth - 30) / alphabet.length;
  const probability = (tree: ContextTree, context: string, state: string): number => tree.nodes[context]?.probability[tree.alphabet.indexOf(state)] ?? 0;
  const cells = contexts.map((context, rowIndex) => `<text class="tt-text tt-small" x="18" y="${72 + rowIndex * rowHeight}">${escape(context)}</text>${alphabet.map((state, stateIndex) => {
    const difference = probability(rightTree, context, state) - probability(leftTree, context, state); const opacity = .12 + .88 * Math.min(Math.abs(difference), 1); const fill = difference >= 0 ? '#ef7fa5' : '#5fc4ee';
    return `<g><rect x="${labelWidth + stateIndex * cellWidth}" y="${53 + rowIndex * rowHeight}" width="${cellWidth - 3}" height="${rowHeight - 3}" rx="3" fill="${fill}" opacity="${opacity}"><title>${escape(names[1])} − ${escape(names[0])}: ${number(difference)}</title></rect><text class="tt-text tt-small" x="${labelWidth + stateIndex * cellWidth + cellWidth / 2}" y="${74 + rowIndex * rowHeight}" text-anchor="middle">${difference > 0 ? '+' : ''}${number(difference, 2)}</text></g>`;
  }).join('')}`).join('');
  const headers = alphabet.map((state, index) => `<text class="tt-muted tt-small" x="${labelWidth + index * cellWidth + cellWidth / 2}" y="42" text-anchor="middle">${escape(state)}</text>`).join('');
  return svg(width, height, title(options.title ?? `${names[1]} − ${names[0]} next-state probability`, width) + headers + cells, 'Group next-state probability difference map', options.theme);
}
